input.command:
cd /tmp && perl -e '
my @tests = (
 ["tab in host","http://a\tb.com"],
 ["newline in host","http://a\nb.com"],
 ["CR in host","http://a\rb.com"],
 ["trailing newline","http://a.com\n"],
 ["trailing CR","http://a.com\r"],
 ["NUL-ish high byte","http://a\xffb.com"],
 ["quote in host","http://a\x27b.com"],
 ["space before colon","http://a.com :80"],
 ["percent bad","http://a%zz.com"],
 ["vertical tab","http://a\x0bb.com"],
 ["formfeed","http://a\x0cb.com"],
 ["bel","http://a\x07b.com"],
);
for my $t (@tests) {
  print "=== [$t->[0]]\n";
  my $pid = open(my $fh, "-|");
  if ($pid == 0) { exec("/workspace/dataset/test5_executable", $t->[1]); exit 1; }
  my @l = <$fh>; close($fh);
  for my $i (0..$#l) { my $s=$l[$i]; $s =~ s/([^\x20-\x7e])/sprintf("\\x%02X",ord($1))/ge; print "  ",$i+1,": [$s]\n"; }
}'
